from pathlib import Path
import hashlib
import json
import subprocess
import sys

root = Path.cwd()
research = root / '.trellis/tasks/10-07-hindsight-template-lifecycle/research'
name = 'b3-core-healthy-owned-files-01'
diff = json.loads((research / 'b3-core-healthy-owned-diff-01-result.json').read_text(encoding='utf-8'))
git = diff['command'][0]
scope = diff['command'][4:]

def paths(*arguments):
    result = subprocess.run([git, *arguments, '--', *scope], check=True, capture_output=True)
    return {value for value in result.stdout.decode('utf-8').split('\0') if value}

untracked = paths('ls-files', '--others', '--exclude-standard', '-z')
changed = paths('diff', '--name-only', '-z') | paths('diff', '--cached', '--name-only', '-z')
owned = sorted(changed | untracked)
issues = []
files = []
for name_path in owned:
    path = root / name_path
    path.resolve().relative_to(root.resolve())
    raw = path.read_bytes()
    try:
        value = raw.decode('utf-8')
    except UnicodeDecodeError:
        issues.append({'path': name_path, 'issue': 'invalid-utf8'})
        continue
    if raw.startswith(b'\xef\xbb\xbf'):
        issues.append({'path': name_path, 'issue': 'utf8-bom'})
    for number, line in enumerate(value.splitlines(), 1):
        if line.endswith((' ', '\t')):
            issues.append({'path': name_path, 'line': number, 'issue': 'trailing-whitespace'})
    if name_path in untracked and value.splitlines() and value.splitlines()[-1] == '':
        issues.append({'path': name_path, 'issue': 'new-blank-line-at-eof'})
    if '/src/' in name_path and path.suffix == '.ts' and not path.name.endswith('.test.ts'):
        index = path.parent / 'index.md'
        if not index.exists() or path.name not in index.read_text(encoding='utf-8'):
            issues.append({'path': name_path, 'issue': 'missing-index-entry'})
    files.append({'path': name_path, 'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw), 'untracked': name_path in untracked})

current = {row['path']: row['sha256'] for row in json.loads((research / (name + '-source.json')).read_text(encoding='utf-8'))}
fixture = 'packages/core/src/testing/hindsight-template-observation-fixtures.ts'
comparisons = {}
for previous in ('healthy-template-green-01', 'healthy-legacy-reuse-01', 'healthy-offline-w6-01', 'healthy-template-types-02', 'healthy-owned-lint-01', 'healthy-observer-final-01'):
    before = {row['path']: row['sha256'] for row in json.loads((research / ('b3-core-' + previous + '-source-after.json')).read_text(encoding='utf-8'))}
    difference = sorted(key for key in before.keys() | current.keys() if before.get(key) != current.get(key))
    expected = [fixture] if previous in ('healthy-template-green-01', 'healthy-legacy-reuse-01', 'healthy-offline-w6-01') else []
    comparisons[previous] = difference
    if difference != expected:
        issues.append({'check': previous, 'issue': 'unexpected-reuse-input-difference', 'actual': difference, 'expected': expected})

manifest = research / (name + '-files.json')
if manifest.exists():
    raise RuntimeError('Keep previous file-check evidence')
manifest.write_text(json.dumps({'files': files, 'sourceComparisons': comparisons, 'issues': issues}, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'fileCount': len(files), 'untrackedFileCount': len(untracked), 'currentInputCount': len(current), 'sourceComparisons': comparisons, 'issues': issues, 'fileInventory': str(manifest)}, indent=2))
sys.exit(1 if issues else 0)
